P=pathlib.Path(__file__).resolve().parent;sys.path.insert(0,str(P.parent));from new_tokenizer import Encoder
sys.path.insert(0,str(P));from paragraphs import Paragraphs,units
enc=Encoder(json.loads((P.parent/'data/tokenizer.json').read_text()));pieces=[bytes.fromhex(x)for x in enc.tok['bytes']]
selection=[('new','0000471631','エコバッグは清潔に！'),('new','0000644680','ナッジを活用した食品ロス削減の取組事例'),('new','0000678958',''),('old','0000369358','家電製品は正しくリサイクルしましょう'),('old','0000384524','混ざると大変')]
reviews=['Natural hygiene advice; specific cleaning actions and selection criterion. First two sentences are prefix because the first is a noun-ending introduction. Third-party entertainer section is not included.','Municipal explanatory prose about nudge and food-waste behavior; third-party student designs elsewhere on page excluded. No claim that all current official text is verified human-only.','Definition, examples, practical routes and environmental reason for reuse form one continuous original unit. External commercial-service sections not included.','Reasoned warning and action about disposal; no unsupported individual/third-party assertions introduced. Original municipal current guidance, not model personal experience.','Explains why contamination undermines recycling, with concrete examples and causal consequence. Continuous original paragraph, not joined unrelated snippets.']
cases=[]
for (kind,ident,heading),review in zip(selection,reviews):
 f=P/'private/discovery'/('osaka-dev-'+ident+'.gz')if kind=='new'else pathlib.Path('/workspace/4k29/training/language/conversation-v2/modern-corpus/private/osaka')/(ident+'.html.gz')
 raw=gzip.decompress(f.read_bytes());q=Paragraphs('mol_contents');q.feed(raw.decode('utf-8'));q.finish();rows,_=units(q.events);matches=[r for r in rows if r['heading']==heading];assert len(matches)==1,(ident,len(matches));r=matches[0];text=r['text'];tokens=enc(text);prefix_sentences=2 if ident=='0000471631'else 1
 boundary=[m.end()for m in re.finditer('。',text)][prefix_sentences-1];expected=text[:boundary].encode();poss=[]
 for j in range(1,min(96,len(tokens))):
  b=b''.join(pieces[t]for t in tokens[:j])
  if b.rstrip()==expected:poss.append(j)
 assert poss,('no exact complete-sentence token boundary',ident)
 n=max(poss);prefix=([1]if r['BOS']else[])+tokens[:n];assert len(prefix)<128
 cases.append(dict(id='osaka-paragraph-'+ident,panel='new_source_heldout_paragraph5',source_url='https://www.city.osaka.lg.jp/kankyo/page/'+ident+'.html',source_sha256=hashlib.sha256(raw).hexdigest(),family='osaka|'+ident,heldout_scope='Entire Osaka source excluded from TRAIN; not independent-author TEST',source_text=text,source_text_sha256=hashlib.sha256(text.encode()).hexdigest(),paragraph_indices=r['paragraph_indices'],original_section_start=r['BOS'],original_section_end=r['EOS'],prefix=prefix,prefix_text=b''.join(pieces[t]for t in prefix).decode(),reference_tokens=tokens[n:]+([2]if r['EOS']else[]),reference_new_sentences=text[boundary:].count('。'),quality_review=review,reviewer='single main assistant, not independent human evaluator',authorship='Official municipal prose; human-only authorship not independently certified',license='CC BY 4.0-compatible municipal reuse policy, third-party scope excluded',license_url='https://www.city.osaka.lg.jp/main/site_policy/0000000160.html',attribution='Source: City of Osaka, individual URL above; extracted for diagnostic evaluation by 4k29, no city endorsement.'))
protocol=dict(status='Frozen before model outputs; exposed research DEV upon use, never sealed TEST',cases=cases,main_generation=dict(decoder='whole-vocabulary greedy',max_new_tokens=160,context=256,context_limit_behavior='reuse inherited sliding final256 tokens without invented BOS; report any crop',stop='token2 EOS or max_new_tokens; no textual postprocessing',save=['full token IDs','raw bytes hex','decoded text','stop reason','input','checkpoint SHA']),scoring=dict(sentence_ending_completion='Report separately, never paragraph success',single_sentence='Natural one sentence separately',paragraph_success='At least two new complete sentences with grammatical Japanese, stable topic and referents, meaningful connection to prefix, no harmful repetition/irrelevant claims, and natural completed thought. EOS and content assessed separately; early EOS alone is not success.',required_reasoning='Read entire unmodified output; a new wording alone is not context understanding',generality='Five source-held-out cases have low statistical power; no independent native-speaker or broad Japanese ability claim'),selection='Source-based quality and exact full-BPE boundary only, no model outputs inspected',further_training='Do not alter this DEV or rubric after observing outputs')
out=P/'PARAGRAPH_DEV_PROTOCOL.json';assert not out.exists(),'Do not overwrite frozen DEV';out.write_text(json.dumps(protocol,ensure_ascii=False,indent=2)+'\n');print('Frozen',len(cases),'cases; references new-sentence counts:',[c['reference_new_sentences']for c in cases])
